<ref name="OoA Instruction Booklet 27">{{Cite Manual|quote= '''{{Big|Pegasus Seeds: Run}}'''<br/>Press the + Control Pad to run in one of eight different directions for as long as the Pegasus Seed effect lasts.|game= OoA|page= 27}}</ref>

